create table if not exists public.platform_report_schedules(id uuid primary key default gen_random_uuid(),name text not null,recipients text[]not null check(cardinality(recipients)between 1 and 20),frequency text not null check(frequency in('daily','weekly','monthly')),active boolean not null default true,next_run_at timestamptz not null default now(),last_run_at timestamptz,created_by uuid not null default auth.uid()references auth.users(id),created_at timestamptz not null default now());create table if not exists public.platform_report_runs(id uuid primary key default gen_random_uuid(),schedule_id uuid not null references public.platform_report_schedules(id)on delete cascade,status text not null check(status in('success','error')),recipients_count integer not null default 0,error text,created_at timestamptz not null default now());alter table public.platform_report_schedules enable row level security;alter table public.platform_report_runs enable row level security;create policy"plataforma gerencia relatorios agendados"on public.platform_report_schedules for all to authenticated using(public.is_platform_admin())with check(public.is_platform_admin());create policy"plataforma consulta execucoes relatorio"on public.platform_report_runs for select to authenticated using(public.is_platform_admin());
do $$declare cmd text;begin select command into cmd from cron.job where jobname='scheduled-reports-runner'limit 1;if cmd is not null then perform cron.unschedule('platform-reports-runner')where exists(select 1 from cron.job where jobname='platform-reports-runner');perform cron.schedule('platform-reports-runner','0 * * * *',replace(cmd,'scheduled-reports-runner','platform-reports-runner'));end if;end$$;
